-- BLUEPRINTS_v1: tables behind the Blueprint Builder (worker routes /blueprints, /blueprints/rules).
-- Run once in Supabase > SQL editor. RLS on with no policies: only the worker (service key) reads or writes.
create table if not exists public.spark_hq_blueprint_rules (id int primary key, data jsonb not null, updated_at timestamptz not null default now(), updated_by text);
alter table public.spark_hq_blueprint_rules enable row level security;
create table if not exists public.spark_hq_blueprints (id uuid primary key default gen_random_uuid(), name text not null, status text not null default 'draft', data jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), updated_by text);
create index if not exists spark_hq_blueprints_name on public.spark_hq_blueprints (lower(name));
alter table public.spark_hq_blueprints enable row level security;

-- Access: super admins get in automatically. Fletcher gets the restricted area (same table Admin > Access writes).

-- Seed: rules from Fletcher's workbooks + the 37 existing One Page Blueprints (generic templates and the duplicate skipped).
) as v(name, data) where not exists (select 1 from public.spark_hq_blueprints b where lower(b.name) = lower(v.name));
